package com.rekluzlabs.makokolorize.ui.screensimport android.graphics.Bitmapimport android.view.WindowManagerimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.widthimport androidx.compose.foundation.rememberScrollStateimport androidx.compose.foundation.text.KeyboardOptionsimport androidx.compose.foundation.verticalScrollimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.automirrored.filled.ArrowBackimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.Iconimport androidx.compose.material3.IconButtonimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.OutlinedTextFieldimport androidx.compose.material3.Scaffoldimport androidx.compose.material3.Sliderimport androidx.compose.material3.Switchimport androidx.compose.material3.Textimport androidx.compose.material3.TextButtonimport androidx.compose.material3.TopAppBarimport androidx.compose.runtime.Composableimport androidx.compose.runtime.DisposableEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableIntStateOfimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.platform.LocalViewimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.text.input.KeyboardTypeimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.rekluzlabs.makokolorize.data.settings.SettingsRepository@OptIn(ExperimentalMaterial3Api::class)@Composablefun SettingsScreen(    onBack: () -> Unit) {    val context = LocalContext.current    val settings = remember { SettingsRepository(context) }    var outputFormat by remember { mutableStateOf(settings.outputFormat) }    var jpegQuality by remember { mutableIntStateOf(settings.jpegQuality) }    var keepAwake by remember { mutableStateOf(settings.keepScreenAwake) }    var saveOriginal by remember { mutableStateOf(settings.saveOriginalAlongsideResult) }    var tileSizeText by remember { mutableStateOf(settings.tileSizeOverride.toString()) }    val view = LocalView.current    DisposableEffect(keepAwake) {        val window = (view.context as? android.app.Activity)?.window        if (keepAwake) {            window?.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)        } else {            window?.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)        }        onDispose {            window?.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)        }    }    Scaffold(        topBar = {            TopAppBar(                title = { Text("Settings") },                navigationIcon = {                    IconButton(onClick = {                        settings.outputFormat = outputFormat                        settings.jpegQuality = jpegQuality                        settings.keepScreenAwake = keepAwake                        settings.saveOriginalAlongsideResult = saveOriginal                        settings.tileSizeOverride = tileSizeText.toIntOrNull() ?: 0                        onBack()                    }) {                        Icon(                            Icons.AutoMirrored.Filled.ArrowBack,                            contentDescription = "Back"                        )                    }                }            )        }    ) { padding ->        Column(            modifier = Modifier                .fillMaxSize()                .padding(padding)                .padding(horizontal = 24.dp)                .verticalScroll(rememberScrollState()),            verticalArrangement = Arrangement.spacedBy(24.dp)        ) {            Spacer(modifier = Modifier.height(8.dp))            // Output format            SettingSectionHeader("Output Format")            Row(                horizontalArrangement = Arrangement.spacedBy(12.dp)            ) {                TextButton(                    onClick = { outputFormat = Bitmap.CompressFormat.JPEG },                    enabled = outputFormat == Bitmap.CompressFormat.JPEG                ) { Text("JPEG") }                TextButton(                    onClick = { outputFormat = Bitmap.CompressFormat.PNG },                    enabled = outputFormat == Bitmap.CompressFormat.PNG                ) { Text("PNG") }            }            // JPEG quality            if (outputFormat == Bitmap.CompressFormat.JPEG) {                SettingSectionHeader("JPEG Quality: $jpegQuality")                Slider(                    value = jpegQuality.toFloat(),                    onValueChange = { jpegQuality = it.toInt() },                    valueRange = 1f..100f,                    steps = 98,                    modifier = Modifier.fillMaxWidth()                )            }            // Keep screen awake            SettingToggle(                title = "Keep screen awake",                description = "Prevent screen from turning off during processing",                checked = keepAwake,                onCheckedChange = { keepAwake = it }            )            // Save original alongside result            SettingToggle(                title = "Save original alongside result",                description = "Save both original and colorized images when exporting",                checked = saveOriginal,                onCheckedChange = { saveOriginal = it }            )            // Tile size override            SettingSectionHeader("Tile Size Override (0 = auto)")            OutlinedTextField(                value = tileSizeText,                onValueChange = { tileSizeText = it.filter { c -> c.isDigit() } },                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),                singleLine = true,                modifier = Modifier.width(120.dp),                placeholder = { Text("0") }            )            Spacer(modifier = Modifier.height(32.dp))        }    }}@Composableprivate fun SettingSectionHeader(title: String) {    Text(        text = title,        fontSize = 14.sp,        fontWeight = FontWeight.Medium,        color = MaterialTheme.colorScheme.onSurfaceVariant    )}@Composableprivate fun SettingToggle(    title: String,    description: String,    checked: Boolean,    onCheckedChange: (Boolean) -> Unit) {    Row(        modifier = Modifier.fillMaxWidth(),        verticalAlignment = Alignment.CenterVertically    ) {        Column(modifier = Modifier.weight(1f)) {            Text(title, fontWeight = FontWeight.Medium)            Text(                description,                fontSize = 12.sp,                color = MaterialTheme.colorScheme.onSurfaceVariant            )        }        Spacer(modifier = Modifier.width(12.dp))        Switch(checked = checked, onCheckedChange = onCheckedChange)    }}